select public.import_course($json$ {"slug":"english-b1-b2","title":"English B1 → B2: Independent User","subtitle":"64 guided hours across 8 modules, built around the Learn → Practise → Produce → Review → Get feedback loop.","description":"A 64-hour guided course that takes a B1 learner to a solid B2. Eight themed modules of eight lessons each cover grammar, vocabulary, listening, reading, speaking and writing, with spaced-repetition vocabulary, AI feedback on every recording and draft, and four assessment checkpoints. Designed for 8 hours a week over 8 weeks, or 45 minutes a day over roughly 9 weeks.","level_from":"B1","level_to":"B2","total_hours":64,"weekly_hours":8,"duration_weeks":8,"daily_minutes_min":20,"daily_minutes_max":45,"daily_flow":[{"block":"warm_up","minutes":3,"label":"Warm-up","description":"Review 5–10 spaced-repetition cards."},{"block":"input","minutes":8,"label":"Input","description":"Short grammar explanation, article or audio."},{"block":"practice","minutes":10,"label":"Practice","description":"Interactive exercises, listening questions or reading tasks."},{"block":"output","minutes":10,"label":"Output","description":"Voice recording, writing prompt or chat-based role-play."},{"block":"feedback","minutes":4,"label":"Feedback","description":"Corrections, alternative phrasing and a progress update."}],"skill_balance":[{"skill":"grammar","hours":10},{"skill":"vocabulary","hours":8},{"skill":"listening","hours":12},{"skill":"reading","hours":10},{"skill":"speaking","hours":12},{"skill":"writing","hours":10},{"skill":"review","hours":2}]} $json$::jsonb) as course_id;

