select public.import_assessments($json$ {"course_slug":"english-b1-b2","checkpoints":[{"code":"b1_consolidation","module":2,"title":"B1 consolidation","timing":"End of Module 2","description":"A grammar quiz on the two module grammar areas, a two-minute recording and a short email. Confirms the learner can operate reliably at B1 before the pace lifts.","minutes":40,"skills":["grammar","speaking","writing"],"tasks":[{"kind":"quiz","title":"Grammar quiz","detail":"24 items: present perfect vs. past simple, narrative tenses, future forms, conditionals.","minutes":12},{"kind":"speaking","title":"Two-minute recording","detail":"Describe a major change in your life and one plan for the next year.","minutes":3},{"kind":"writing","title":"Short email","detail":"An informal email of 120–150 words catching up with a friend.","minutes":15}]},{"code":"mid_course_review","module":4,"title":"Mid-course review","timing":"End of Module 4","description":"A listening task, a reading task and a 180-word review. Checks that comprehension keeps pace with production.","minutes":45,"skills":["listening","reading","writing"],"tasks":[{"kind":"listening","title":"Listening task","detail":"Two short audio extracts with detail and inference questions.","minutes":12},{"kind":"reading","title":"Reading task","detail":"A 400-word article with skimming, scanning and inference questions.","minutes":13},{"kind":"writing","title":"Review","detail":"A 180-word review of an app, film or product.","minutes":20}]},{"code":"b2_readiness","module":6,"title":"B2 readiness","timing":"End of Module 6","description":"A 200-word essay and a three-minute opinion talk. The first checkpoint scored against B2 criteria.","minutes":55,"skills":["writing","speaking"],"tasks":[{"kind":"writing","title":"Argument essay","detail":"200 words on a health or ethics question.","minutes":25},{"kind":"speaking","title":"Three-minute opinion talk","detail":"Present and defend a position, then answer two follow-up questions.","minutes":10}]},{"code":"final_b2_assessment","module":8,"title":"Final B2 assessment","timing":"End of Module 8","description":"Timed reading and listening, a 200–220-word essay and a speaking interview. Produces the personalised B2-readiness report.","minutes":90,"skills":["reading","listening","writing","speaking"],"tasks":[{"kind":"reading","title":"Timed reading","detail":"Two texts in 25 minutes: meaning, information, opinion, detail.","minutes":25},{"kind":"listening","title":"Timed listening","detail":"Three extracts in 20 minutes with note-taking.","minutes":20},{"kind":"writing","title":"Essay","detail":"200–220 words arguing a position with examples.","minutes":30},{"kind":"speaking","title":"Speaking interview","detail":"Three-minute talk plus follow-up questions on organisation and pronunciation.","minutes":15}]}],"badges":[{"code":"first_monologue","title":"First 2-Minute Monologue","icon":"🎙️","xp":60,"description":"Record a spoken answer of at least two minutes and have it evaluated.","criteria":{"type":"speaking_seconds","seconds":120}},{"code":"essay_completed","title":"Essay Completed","icon":"✍️","xp":70,"description":"Submit an essay or formal piece and receive feedback.","criteria":{"type":"writing_tasks","count":1}},{"code":"streak_7","title":"7-Day Streak","icon":"🔥","xp":50,"description":"Study on seven consecutive days.","criteria":{"type":"streak_days","days":7}},{"code":"collocations_100","title":"100 Collocations Learned","icon":"🧩","xp":100,"description":"Recall 100 vocabulary items correctly in review.","criteria":{"type":"collocations","count":100}},{"code":"speaking_lab_10","title":"Ten Recordings","icon":"🎧","xp":80,"description":"Submit ten speaking recordings across the course.","criteria":{"type":"speaking_seconds","seconds":600}}]} $json$::jsonb) as assessments;

-- 3. Modules, lessons, blocks, practice items, inputs, tasks -------------
select public.import_modules($json$ {"course_slug":"english-b1-b2","modules":[{"number":1,"title":"Everyday fluency","summary":"Talk about yourself with confidence: life history, routines, personality and change.","hours":8,"vocabularyTopic":"Personality, routines, memories and change","grammar":[{"key":"present-perfect-vs-past-simple","name":"Present perfect vs. past simple","explanation":"Use the past simple for a finished action at a known past time, and the present perfect for experience or a situation that still matters now.","keyPoints":["Past simple pairs with finished time markers: in 2019, yesterday, last summer.","Present perfect never takes a finished time marker: I have visited Lisbon three times.","Use have been (experience) rather than have gone (still away)."],"example":"I started my first job in 2019, and I have worked in three different cities since then.","items":[{"prompt":"I ___ my first job in 2019.","options":["have started","started","did start"],"answer":"started","explanation":"A finished time (2019) takes the past simple.","difficulty":1},{"prompt":"Which sentence describes life experience rather than a finished event?","options":["I have visited Lisbon three times.","I visited Lisbon in 2021.","I was visiting Lisbon last year."],"answer":"I have visited Lisbon three times.","explanation":"Experience with no fixed time uses the present perfect.","difficulty":1},{"prompt":"I ___ never flown alone before this trip.","options":["did","have","was"],"answer":"have","explanation":"Present perfect with 'never' describes experience up to now.","difficulty":1}]},{"key":"narrative-tenses","name":"Narrative tenses","explanation":"When you tell a story, past continuous sets the scene, past simple moves the action forward, and past perfect explains what had already happened.","keyPoints":["Past continuous frames the background: I was walking home when I saw the message.","Past perfect marks the earlier of two past events: the film had already started.","Keep one main timeline; use past perfect only when the order matters."],"example":"I had been waiting for hours when the bus finally arrived, so I walked the last two kilometres.","items":[{"prompt":"When I arrived, the film ___.","options":["already started","had already started","was already starting"],"answer":"had already started","explanation":"Past perfect shows the film started before you arrived.","difficulty":2},{"prompt":"I ___ home when I saw the message.","options":["walked","was walking","had walked"],"answer":"was walking","explanation":"Past continuous sets the background action interrupted by a shorter event.","difficulty":1},{"prompt":"We ___ for hours before the bus finally came.","options":["waited","had been waiting","were waiting"],"answer":"had been waiting","explanation":"Past perfect continuous emphasises duration before a later past moment.","difficulty":3}]}],"vocab":[{"term":"outgoing","pos":"adjective","definition":"sociable and happy to meet new people","example":"She is more outgoing now than she was at school.","collocations":["an outgoing personality","naturally outgoing"],"translation":"extrovertido","audioRef":"module-1/outgoing.mp3"},{"term":"reserved","pos":"adjective","definition":"quiet and slow to show feelings or opinions","example":"He seems reserved until you get to know him.","collocations":["a reserved manner","quiet and reserved"],"translation":"reservado","audioRef":"module-1/reserved.mp3"},{"term":"get on with","pos":"phrasal verb","definition":"have a good, friendly relationship with someone","example":"I get on with my flatmates really well.","collocations":["get on well with","easy to get on with"],"translation":"llevarse bien con","audioRef":"module-1/get-on-with.mp3"},{"term":"set in your ways","pos":"phrase","definition":"fixed in your habits and unwilling to change them","example":"My grandfather is kind, but he is set in his ways.","collocations":["become set in your ways","rather set in his ways"],"translation":"ser de costumbres fijas","audioRef":"module-1/set-in-your-ways.mp3"},{"term":"turning point","pos":"noun","definition":"the moment at which something changes decisively","example":"Moving abroad was the turning point in my career.","collocations":["a major turning point","reach a turning point"],"translation":"punto de inflexión","audioRef":"module-1/turning-point.mp3"},{"term":"settle down","pos":"phrasal verb","definition":"start a calm, stable life in one place","example":"They settled down in Valencia after years of travelling.","collocations":["settle down somewhere","settle down with someone"],"translation":"establecerse","audioRef":"module-1/settle-down.mp3"},{"term":"look back on","pos":"phrasal verb","definition":"think about something that happened in the past","example":"I look back on that year with real affection.","collocations":["look back on the past","look back fondly"],"translation":"recordar con nostalgia","audioRef":"module-1/look-back-on.mp3"},{"term":"bring up","pos":"phrasal verb","definition":"care for and raise a child","example":"She was brought up by her grandparents in Galicia.","collocations":["bring up children","be brought up abroad"],"translation":"criar","audioRef":"module-1/bring-up.mp3"},{"term":"come round to","pos":"phrasal verb","definition":"gradually accept an idea or opinion","example":"My parents came round to the idea after a few months.","collocations":["come round to the idea","slowly come round"],"translation":"acabar aceptando","audioRef":"module-1/come-round-to.mp3"},{"term":"get used to","pos":"phrase","definition":"become familiar with something new","example":"It took me a year to get used to the climate.","collocations":["get used to the weather","slowly get used to"],"translation":"acostumbrarse a","audioRef":"module-1/get-used-to.mp3"},{"term":"upbringing","pos":"noun","definition":"the way a person was raised as a child","example":"Her upbringing was strict but very warm.","collocations":["a strict upbringing","a happy upbringing"],"translation":"educación, crianza","audioRef":"module-1/upbringing.mp3"},{"term":"take after","pos":"phrasal verb","definition":"look or behave like an older family member","example":"People say I take after my mother.","collocations":["take after your father","clearly take after"],"translation":"parecerse a","audioRef":"module-1/take-after.mp3"}],"inputs":[{"kind":"listening","lesson":2,"title":"Three people, three changes","source":"Studio original — mixed accents","accent":"British, Irish and American","seconds":95,"body":"LAURA: I had been teaching for six years when I finally booked a one-way ticket. I was terrified, but it turned out to be the best decision I have ever made. DIEGO: My parents came round to the idea eventually. At first they thought I was throwing away a good job, and to be honest, so did I. MARI: I only really settled down at thirty-five. Before that I was moving every eighteen months, and I had never owned furniture that I actually chose myself.","questions":[{"prompt":"How long had Laura been teaching before she booked the ticket?","options":["Three years","Six years","Eighteen months"],"answer":"Six years"},{"prompt":"How do Diego's parents feel now?","options":["They still oppose the decision","They have slowly accepted it","They never found out"],"answer":"They have slowly accepted it"},{"prompt":"What does Mari say about her earlier life?","options":["She moved very often","She never had a job","She bought furniture every year"],"answer":"She moved very often"}],"speaker_accents":[{"speaker":"LAURA","accent":"en-GB","label":"British"},{"speaker":"DIEGO","accent":"en-IE","label":"Irish"},{"speaker":"MARI","accent":"en-US","label":"American"}],"audioRef":"module-1/three-people-three-changes.mp3","audioStatus":"bundled"},{"kind":"reading","lesson":6,"title":"The year everything changed","source":"Studio original","body":"Most people can name the year their life changed. For Ana it was 2020, when the restaurant she managed closed for good. She had spent a decade building a career she loved, and suddenly it had gone. What she remembers now is not the loss but the noise of it: one week she was planning a menu, the next she was queuing for a job she had never imagined doing. Two years later she runs a small cooking school, and she says she would not go back. The turning point, she insists, was not the closure itself but the first morning she stopped waiting for things to return to normal.","questions":[{"prompt":"What did Ana lose in 2020?","options":["A cooking school","The restaurant she managed","A house"],"answer":"The restaurant she managed"},{"prompt":"What does she remember most clearly?","options":["The suddenness of the change","The money she earned","The people she hired"],"answer":"The suddenness of the change"},{"prompt":"What does Ana identify as her real turning point?","options":["Losing her job","Opening the school","Accepting that normal had gone"],"answer":"Accepting that normal had gone"}],"audioRef":"module-1/the-year-everything-changed.mp3","audioStatus":"bundled"}],"speaking":[{"kind":"prompt_card","title":"Describe a major change in your life","prompt":"Describe a major change in your life. What happened, how did you feel at the time, and what did you learn? Speak for 90 seconds.","seconds":90,"phrases":["What stands out is...","At the time I felt...","Looking back, I would say..."],"linkers":["because","although","in the end"],"terms":["turning point","settle down","get used to"]},{"kind":"role_play","title":"Role-play: catching up with an old friend","prompt":"You meet a friend you have not seen for five years. Ask about their life, react to their news, and share one change of your own. Two minutes.","seconds":120,"phrases":["How have you been?","That sounds like quite a change.","Have you kept in touch with...?"],"linkers":["actually","to be honest","by the way"],"terms":["upbringing","outgoing","take after"]},{"kind":"shadowing","title":"Shadowing: storytelling rhythm","prompt":"Repeat the model story line by line, copying the stress on content words and the short pause at each thought group.","seconds":60,"phrases":["I had been living there / for about a year / when everything changed."],"linkers":["when","before","by the time"],"terms":["had been","turning point"]}],"writing":{"title":"Informal email: news and changes","prompt":"Write an informal email to a friend you have not contacted for a year. Tell them about one change in your life, ask two questions, and suggest meeting. 120–150 words.","format":"informal email","wordMin":120,"wordMax":150,"outline":{"analyze":"Purpose: share news and re-connect. Audience: a friend. Register: informal but correct.","plan":"Greeting → one clear change → two questions → suggestion → sign-off.","draft":"Use present perfect for news, past simple for finished details, and at least two phrasal verbs.","improve":"Replace 'very good' and 'nice' with precise adjectives; add one linker per paragraph.","review":"Check the word count, the greeting and closing, and that both questions are clear."}},"lessons":[{"title":"Life so far: present perfect vs. past simple","objective":"Separate finished past events from life experience in a short personal history.","canDo":"I can tell the story of my life so far, using the past simple for finished events and the present perfect for experience.","skill":"grammar","input":"reading","outputTitle":"Life story in six sentences","output":"Record six sentences about your life: three finished events in the past simple and three experiences in the present perfect.","targetSeconds":60},{"title":"Listening: three people, three changes","objective":"Catch time markers and attitude in short personal stories told in three accents.","canDo":"I can follow a short personal story in a familiar accent and identify the speaker's attitude.","skill":"listening","input":"listening","outputTitle":"Retell one story","output":"Retell one of the three stories in 60 seconds, keeping the timeline in order.","targetSeconds":60},{"title":"Vocabulary: personality and routines","objective":"Describe character and daily habits with precise B1 collocations instead of 'nice' and 'good'.","canDo":"I can describe someone's personality and daily routine using at least six topic collocations.","skill":"vocabulary","input":"reading","outputTitle":"Describe a person you know well","output":"Record a 60-second description of a person you know well using five of the new collocations.","targetSeconds":60},{"title":"Speaking: describing a major change","objective":"Structure a 90-second account of a change with a clear beginning, middle and reflection.","canDo":"I can speak for 90 seconds about a change in my life, linking ideas and reflecting at the end.","skill":"speaking","input":"listening","outputTitle":"90-second monologue","output":"Use the prompt card below: what happened, how you felt, what you learned.","targetSeconds":90},{"title":"Narrative tenses: telling it properly","objective":"Combine past continuous, past simple and past perfect so a story's timeline is never ambiguous.","canDo":"I can tell a story with a clear timeline, using past perfect only where the order matters.","skill":"grammar","input":"listening","outputTitle":"A day that went wrong","output":"Tell a 90-second story about a day that went wrong, with at least one past perfect sentence.","targetSeconds":90},{"title":"Reading: the year everything changed","objective":"Identify the main idea, a detail and an inferred attitude in a short narrative article.","canDo":"I can read a short article about someone's life change and explain what the writer implies.","skill":"reading","input":"reading","outputTitle":"Summary and opinion","output":"Write four sentences: two summarising the article and two saying whether you agree with Ana.","wordRange":[60,90]},{"title":"Writing: informal email about change","objective":"Plan, draft and edit a 120–150-word informal email with a clear purpose and audience.","canDo":"I can write an informal email of 120–150 words that shares news, asks questions and suggests a plan.","skill":"writing","input":"reading","outputTitle":"Informal email","output":"Write the email, then revise it once for vocabulary range and one linker per paragraph.","wordRange":[120,150]},{"title":"Review: module 1 consolidation","objective":"Recall the module's tenses and vocabulary under light time pressure and identify your weakest area.","canDo":"I can use the module's two tense systems and twelve expressions accurately in a short review task.","skill":"review","input":"listening","outputTitle":"Mixed review","output":"Do the practice set twice: once untimed, once in six minutes. Note every item you missed.","targetSeconds":120}],"releaseStage":"live"},{"number":2,"title":"Work and study","summary":"Careers, education and plans: talk about the future with accuracy and compare options.","hours":8,"vocabularyTopic":"Careers, education, goals and workplace communication","grammar":[{"key":"future-forms","name":"Future forms: plans, predictions, arrangements","explanation":"Choose the future form by meaning: going to for intentions, will for predictions and spontaneous decisions, present continuous for fixed arrangements.","keyPoints":["Fixed arrangement: I'm meeting my manager at nine tomorrow.","Intention: I'm going to apply for the internal role.","Prediction or offer: It will probably take two years. I'll send it now."],"example":"I'm meeting the recruiter on Thursday, and I'm going to take the online course before then; it will make the interview easier.","items":[{"prompt":"I ___ the recruiter at nine tomorrow — it is already in my calendar.","options":["will meet","am meeting","meet"],"answer":"am meeting","explanation":"A fixed arrangement takes the present continuous.","difficulty":1},{"prompt":"Which sentence expresses an intention?","options":["I'm going to retrain next year.","I'll retrain, I promise.","I retrain next year."],"answer":"I'm going to retrain next year.","explanation":"'Going to' expresses a plan or intention rather than a promise.","difficulty":2},{"prompt":"The job ___ harder than it looks.","options":["is being","will be","is going"],"answer":"will be","explanation":"Predictions about the future use will + infinitive.","difficulty":1}]},{"key":"conditionals-1-2","name":"First and second conditionals","explanation":"First conditional covers realistic future possibilities; second conditional covers imagined or unlikely present situations and polite proposals.","keyPoints":["First: If I finish the course, I will ask for a promotion.","Second: If I had more time, I would study design.","Use were with I/he/she in formal second conditionals: If I were you..."],"example":"If I pass the exam in June, I'll apply for the master's; if I had the money now, I'd already be enrolled.","items":[{"prompt":"If I ___ the exam in June, I will apply for the master's.","options":["pass","passed","will pass"],"answer":"pass","explanation":"The first conditional uses the present simple in the if-clause.","difficulty":1},{"prompt":"If I had more time, I ___ a second language.","options":["will learn","would learn","learn"],"answer":"would learn","explanation":"Imagined present situations take would + infinitive.","difficulty":1},{"prompt":"Which sentence is the most diplomatic way to give advice?","options":["If I am you, I apply.","If I were you, I would negotiate the salary.","If I was you, I will negotiate."],"answer":"If I were you, I would negotiate the salary.","explanation":"'If I were you, I would...' is the standard diplomatic formula.","difficulty":2}]}],"vocab":[{"term":"career path","pos":"noun","definition":"the series of jobs a person does over their working life","example":"Teaching was not the career path she expected.","collocations":["choose a career path","change career path"],"translation":"trayectoria profesional","audioRef":"module-2/career-path.mp3"},{"term":"apply for","pos":"phrasal verb","definition":"formally ask for a job, course or permission","example":"I applied for three roles last week.","collocations":["apply for a job","apply for funding"],"translation":"solicitar","audioRef":"module-2/apply-for.mp3"},{"term":"take on","pos":"phrasal verb","definition":"accept responsibility or employ someone","example":"She took on more responsibility without a pay rise.","collocations":["take on a role","take on staff"],"translation":"asumir, contratar","audioRef":"module-2/take-on.mp3"},{"term":"workload","pos":"noun","definition":"the amount of work a person has to do","example":"My workload doubles in September.","collocations":["a heavy workload","manage your workload"],"translation":"carga de trabajo","audioRef":"module-2/workload.mp3"},{"term":"deadline","pos":"noun","definition":"the latest time by which something must be finished","example":"We missed the deadline by two days.","collocations":["meet a deadline","a tight deadline"],"translation":"fecha límite","audioRef":"module-2/deadline.mp3"},{"term":"qualification","pos":"noun","definition":"an exam pass or official skill that allows you to do something","example":"The role requires a teaching qualification.","collocations":["gain a qualification","formal qualifications"],"translation":"titulación","audioRef":"module-2/qualification.mp3"},{"term":"promotion","pos":"noun","definition":"a move to a more important position at work","example":"He got a promotion after eighteen months.","collocations":["get a promotion","be offered a promotion"],"translation":"ascenso","audioRef":"module-2/promotion.mp3"},{"term":"job satisfaction","pos":"noun","definition":"the feeling that your work is worthwhile","example":"Job satisfaction matters more to me than salary.","collocations":["high job satisfaction","a sense of job satisfaction"],"translation":"satisfacción laboral","audioRef":"module-2/job-satisfaction.mp3"},{"term":"retrain","pos":"verb","definition":"learn new skills in order to change career","example":"He retrained as a nurse at forty.","collocations":["retrain as a teacher","retrain mid-career"],"translation":"reciclarse profesionalmente","audioRef":"module-2/retrain.mp3"},{"term":"short-term contract","pos":"noun","definition":"an agreement to work for a limited period","example":"She started on a short-term contract and stayed five years.","collocations":["sign a short-term contract","renew a contract"],"translation":"contrato temporal","audioRef":"module-2/short-term-contract.mp3"},{"term":"get ahead","pos":"phrasal verb","definition":"become more successful than others","example":"Networking helped her get ahead quickly.","collocations":["get ahead in your career","hard work to get ahead"],"translation":"progresar","audioRef":"module-2/get-ahead.mp3"},{"term":"burn out","pos":"phrasal verb","definition":"become exhausted and unable to work from too much stress","example":"He burnt out after two years of twelve-hour days.","collocations":["risk burning out","burn out quickly"],"translation":"sufrir agotamiento","audioRef":"module-2/burn-out.mp3"}],"inputs":[{"kind":"listening","lesson":2,"title":"A careers podcast: two routes","source":"Studio original — panel clip","accent":"British and Canadian","seconds":100,"body":"HOST: So, Priya, you left banking at thirty-two. PRIYA: I did, and everyone thought I had lost my mind. I had a good salary, but I was going to burn out, I could feel it. The plan was to take six months off and then retrain as a data analyst. HOST: And it worked? PRIYA: Mostly. The studying was harder than the job had been, but I get far more job satisfaction now. If I were starting again, I would save more money first, though.","questions":[{"prompt":"How old was Priya when she left banking?","options":["Twenty-two","Thirty-two","Forty"],"answer":"Thirty-two"},{"prompt":"What did she find hardest?","options":["Studying","Her old salary","Finding a job"],"answer":"Studying"},{"prompt":"What would she change if she started again?","options":["She would stay in banking","She would save more money first","She would study for longer"],"answer":"She would save more money first"}],"speaker_accents":[{"speaker":"HOST","accent":"en-GB","label":"British"},{"speaker":"PRIYA","accent":"en-CA","label":"Canadian"}],"audioRef":"module-2/a-careers-podcast-two-routes.mp3","audioStatus":"actor_pending"},{"kind":"reading","lesson":7,"title":"Is a degree still worth it?","source":"Studio original","body":"For decades the advice was simple: go to university, get a degree, get ahead. That advice still holds for many careers, especially medicine and law, but it is no longer automatic. Employers increasingly ask what a candidate can do rather than where they studied. Short-term contracts, portfolio careers and mid-career retraining have made the single, linear career path much rarer. None of this means a degree is wasted. It means the return depends on the subject, the country and, above all, what the student does with the three years beyond attending lectures.","questions":[{"prompt":"What is the article's main point?","options":["A degree is no longer automatically worth it","Degrees are worthless","Everyone should study medicine"],"answer":"A degree is no longer automatically worth it"},{"prompt":"What do employers increasingly value?","options":["Where you studied","What you can do","How long you studied"],"answer":"What you can do"},{"prompt":"Which factor does the writer highlight above all?","options":["The country","The subject","What the student does beyond lectures"],"answer":"What the student does beyond lectures"}],"audioRef":"module-2/is-a-degree-still-worth-it.mp3","audioStatus":"tts"}],"speaking":[{"kind":"prompt_card","title":"Compare two career paths","prompt":"Compare two career paths you know well. Which would you choose, and why? Speak for two minutes.","seconds":120,"phrases":["On the one hand...","What appeals to me is...","If I had to choose..."],"linkers":["whereas","on balance","for that reason"],"terms":["career path","job satisfaction","workload"]},{"kind":"role_play","title":"Role-play: the job interview","prompt":"You are interviewing for a role you are slightly under-qualified for. Answer three questions about your plans, your weaknesses and why you want the job. Two minutes.","seconds":120,"phrases":["I'm going to...","One thing I'm working on is...","What attracts me most is..."],"linkers":["because","although","in particular"],"terms":["short-term contract","qualification","take on"]},{"kind":"shadowing","title":"Shadowing: future forms in fast speech","prompt":"Shadow the clip twice, paying attention to how going to is reduced to gonna and how will merges with the subject.","seconds":60,"phrases":["I'm going to apply / as soon as I finish the course.","It'll probably take / about six months."],"linkers":["as soon as","before","by then"],"terms":["going to","will"]}],"writing":{"title":"Opinion paragraph: work and study","prompt":"Write a 150-word opinion paragraph answering: is a university degree still the best route to a good career? Give a clear position and two reasons.","format":"opinion paragraph","wordMin":140,"wordMax":160,"outline":{"analyze":"Purpose: argue a position. Audience: an educated general reader. Format: one paragraph or two short ones.","plan":"Position in the first sentence → reason one with an example → reason two → concession → restated position.","draft":"Use one first or second conditional and two future forms.","improve":"Vary sentence openings; replace 'a lot of' with a precise quantifier.","review":"Check the position is visible in the first and last sentences."}},"lessons":[{"title":"Future forms: plans, predictions, arrangements","objective":"Choose between going to, will and the present continuous according to meaning, not habit.","canDo":"I can talk about my plans, arrangements and predictions using the right future form.","skill":"grammar","input":"listening","outputTitle":"Next twelve months","output":"Record 60 seconds on your plans for the next year: three arrangements and two predictions.","targetSeconds":60},{"title":"Listening: a careers podcast","objective":"Extract dates, reasons and hypothetical regrets from a two-speaker interview.","canDo":"I can follow an interview about a career change and note the reasons behind the decision.","skill":"listening","input":"listening","outputTitle":"Note-taking","output":"Take notes under three headings — decision, difficulty, advice — then summarise in three sentences.","wordRange":[50,80]},{"title":"Vocabulary: careers and the workplace","objective":"Use twelve workplace collocations accurately in speech and writing.","canDo":"I can describe a job, its pressures and its rewards using precise workplace vocabulary.","skill":"vocabulary","input":"reading","outputTitle":"Describe your job or course","output":"Record 60 seconds describing your job or course with six of the new expressions.","targetSeconds":60},{"title":"Speaking: comparing two career paths","objective":"Compare options fairly and reach a justified conclusion in two minutes.","canDo":"I can compare two options, weigh them up and justify a choice with linking language.","skill":"speaking","input":"listening","outputTitle":"Two-minute comparison","output":"Use the prompt card: compare, weigh up, decide.","targetSeconds":120},{"title":"First conditional: realistic futures","objective":"Build first-conditional sentences for realistic possibilities and consequences.","canDo":"I can talk about realistic future possibilities and their consequences.","skill":"grammar","input":"reading","outputTitle":"If... then","output":"Record six first-conditional sentences about your studies or work.","targetSeconds":60},{"title":"Second conditional: imagined options","objective":"Use the second conditional for imaginary situations and diplomatic advice.","canDo":"I can discuss imagined situations and give diplomatic advice with the second conditional.","skill":"grammar","input":"listening","outputTitle":"If I could change one thing","output":"Speak for 60 seconds: if you could change one thing about your working life, what would it be?","targetSeconds":60},{"title":"Reading: is a degree still worth it?","objective":"Identify the writer's argument, a concession and the key supporting factor.","canDo":"I can read an argumentative article and separate the main claim from the concession.","skill":"reading","input":"reading","outputTitle":"Argument map","output":"Write the main claim, one concession and your own view in five sentences.","wordRange":[70,100]},{"title":"Writing: opinion paragraph","objective":"State and support a position in 150 words with a clear structure.","canDo":"I can write a 150-word opinion paragraph with a clear position and two supported reasons.","skill":"writing","input":"reading","outputTitle":"Opinion paragraph","output":"Draft, then edit for sentence variety and one conditional.","wordRange":[140,160]}],"releaseStage":"live"}]} $json$::jsonb) as imported_modules_1_2;

select public.import_modules($json$ {"course_slug":"english-b1-b2","modules":[{"number":3,"title":"Travel and culture","summary":"Move between cultures: describe places, compare customs and question tourist behaviour.","hours":8,"vocabularyTopic":"Travel, traditions, global issues and cultural differences","grammar":[{"key":"passive-voice","name":"Passive voice in present and past","explanation":"Use the passive when the action matters more than the doer, or when the doer is obvious, unknown or already understood.","keyPoints":["Present passive: The old town is visited by two million people a year.","Past passive: The temple was built in the eleventh century.","Keep the agent with by only when it adds information."],"example":"The festival is celebrated every spring, and the square was decorated by local families for generations.","items":[{"prompt":"The temple ___ in the eleventh century.","options":["built","was built","is building"],"answer":"was built","explanation":"A finished past action with an unknown or unimportant agent takes the past passive.","difficulty":1},{"prompt":"Choose the best sentence for a travel guide.","options":["Two million people visit the old town every year.","The old town is visited by two million people every year.","The old town visits two million people every year."],"answer":"The old town is visited by two million people every year.","explanation":"Guides foreground the place, so the passive keeps the old town as the topic.","difficulty":2},{"prompt":"When can 'by + agent' be dropped?","options":["Never","When the agent is unknown, obvious or unimportant","Only in the past tense"],"answer":"When the agent is unknown, obvious or unimportant","explanation":"The agent is optional; include it only if it carries new information.","difficulty":1}]},{"key":"relative-clauses","name":"Relative clauses: defining and non-defining","explanation":"Defining clauses identify which person or place you mean and take no commas; non-defining clauses add extra information and always take commas.","keyPoints":["Defining: The village that we visited is now a tourist trap.","Non-defining: Lisbon, which I visited last year, is crowded in August.","Never use that in a non-defining clause, and never drop the relative pronoun after a comma."],"example":"The guide, who grew up in the old quarter, showed us a market that no tourist ever finds.","items":[{"prompt":"Lisbon, ___ I visited last year, is crowded in August.","options":["that","which","where"],"answer":"which","explanation":"Non-defining clauses about a thing take which, never that.","difficulty":1},{"prompt":"Which sentence needs commas?","options":["The guide who grew up here knows every street.","My brother who lives in Berlin is visiting.","Both, depending on meaning"],"answer":"Both, depending on meaning","explanation":"Commas change meaning: with them the clause is extra information; without them it identifies the person.","difficulty":3},{"prompt":"The town ___ we stayed had no tourists at all.","options":["which","where","who"],"answer":"where","explanation":"Where replaces a place adverbial: we stayed in the town.","difficulty":2}]}],"vocab":[{"term":"get around","pos":"phrasal verb","definition":"travel from place to place","example":"It is easy to get around the city by tram.","collocations":["get around easily"],"translation":"moverse por","audioRef":"module-3/get-around.mp3"},{"term":"off the beaten track","pos":"phrase","definition":"away from the popular tourist routes","example":"The village is off the beaten track but worth the trip.","collocations":["far off the beaten track"],"translation":"fuera de los circuitos turísticos","audioRef":"module-3/off-the-beaten-track.mp3"},{"term":"customs","pos":"noun","definition":"traditional ways of behaving in a society","example":"Removing your shoes indoors is a local custom.","collocations":["local customs","respect local customs"],"translation":"costumbres","audioRef":"module-3/customs.mp3"},{"term":"landmark","pos":"noun","definition":"an easily recognised building or place","example":"The cathedral is the city's best-known landmark.","collocations":["a famous landmark"],"translation":"punto de referencia","audioRef":"module-3/landmark.mp3"},{"term":"culture shock","pos":"noun","definition":"the disorientation of living in an unfamiliar culture","example":"She had real culture shock in her first month.","collocations":["experience culture shock"],"translation":"choque cultural","audioRef":"module-3/culture-shock.mp3"},{"term":"blend in","pos":"phrasal verb","definition":"look and behave like the people around you","example":"Learning a few words helps you blend in.","collocations":["blend in with locals"],"translation":"integrarse","audioRef":"module-3/blend-in.mp3"},{"term":"tourist trap","pos":"noun","definition":"an expensive place that exists mainly for tourists","example":"The restaurant by the station is a tourist trap.","collocations":["avoid the tourist traps"],"translation":"trampa para turistas","audioRef":"module-3/tourist-trap.mp3"},{"term":"cultural heritage","pos":"noun","definition":"the traditions and monuments a society inherits","example":"The old quarter is protected as cultural heritage.","collocations":["preserve cultural heritage"],"translation":"patrimonio cultural","audioRef":"module-3/cultural-heritage.mp3"},{"term":"overcrowding","pos":"noun","definition":"too many people in one place","example":"Overcrowding has pushed rents up in the centre.","collocations":["tackle overcrowding"],"translation":"masificación","audioRef":"module-3/overcrowding.mp3"},{"term":"respectful","pos":"adjective","definition":"showing respect for people or customs","example":"Dress respectfully when you visit a temple.","collocations":["respectful of local customs"],"translation":"respetuoso","audioRef":"module-3/respectful.mp3"}],"inputs":[{"kind":"listening","lesson":2,"title":"Travel podcast: the case for slow travel","source":"Studio original — travel podcast","accent":"Australian","seconds":90,"body":"People often ask me how many countries I have been to, and I have started saying that I have no idea, because the number tells you nothing. I spent three weeks in one town in Portugal last spring. I learned the baker's name. I was invited to a birthday party. That would never have happened if I had been moving every two days. Slow travel is not about seeing less; it is about being seen, and remembered, as a guest rather than a customer.","questions":[{"prompt":"Why does the speaker reject the country count?","options":["It says nothing about the experience","She has forgotten the number","It is too difficult to count"],"answer":"It says nothing about the experience"},{"prompt":"What did she do last spring?","options":["Visited ten countries","Stayed three weeks in one town","Moved every two days"],"answer":"Stayed three weeks in one town"}],"speaker_accents":[{"speaker":"PRESENTER","accent":"en-AU","label":"Australian"}],"audioRef":"module-3/travel-podcast-the-case-for-slow-travel.mp3","audioStatus":"actor_pending"},{"kind":"reading","lesson":7,"title":"When tourism becomes too much","source":"Studio original","body":"Venice is not alone. From Barcelona to Kyoto, cities that were built for residents are now shaped by visitors. Short-let flats have pushed rents up, and the bakery that survived for sixty years has been replaced by a shop selling souvenirs made elsewhere. Some cities have responded with visitor taxes, caps on cruise ships or bans on new short-term lets. None of these measures is popular with everyone. Yet the question behind them is simple: is a city a place to live, or a place to be seen? Most residents would answer both, and they would add that the balance has tipped.","questions":[{"prompt":"What is the article mainly about?","options":["The effects of mass tourism on cities","The best time to visit Venice","How to book cheap accommodation"],"answer":"The effects of mass tourism on cities"},{"prompt":"Which measure is mentioned?","options":["Caps on cruise ships","Free entry to museums","Closing all bakeries"],"answer":"Caps on cruise ships"}],"audioRef":"module-3/when-tourism-becomes-too-much.mp3","audioStatus":"tts"}],"speaking":[{"kind":"prompt_card","title":"Should tourists follow local customs strictly?","prompt":"Some travellers say you should always follow local customs; others say visitors pay for tolerance. Give your view with two examples. Two minutes.","seconds":120,"phrases":["It depends on...","Where I draw the line is...","A good example is..."],"linkers":["whereas","however","in my experience"],"terms":["customs","respectful","cultural heritage"]},{"kind":"role_play","title":"Role-play: the travel problem","prompt":"Your flight is cancelled and the hotel has lost your booking. Explain the problem calmly, ask for options and negotiate a solution with the agent. Two minutes.","seconds":120,"phrases":["I'm afraid there seems to be a problem.","Would it be possible to...?","What would you suggest?"],"linkers":["so","unfortunately","in that case"],"terms":["get around","tourist trap","overcrowding"]},{"kind":"shadowing","title":"Shadowing: describing places with the passive","prompt":"Shadow the model audio twice, copying the weak forms in is visited, was built and is known.","seconds":60,"phrases":["The old town / is visited / by two million people / every year."],"linkers":["which","where","by"],"terms":["is built","was visited"]}],"writing":{"title":"Descriptive article: a place worth protecting","prompt":"Write a 160–180-word descriptive article about a place you know that is changing because of tourism. Describe it, explain what is changing, and suggest one measure.","format":"descriptive article","wordMin":160,"wordMax":180,"outline":{"analyze":"Purpose: inform and persuade. Audience: curious travellers. Register: semi-formal.","plan":"Vivid opening → what makes the place special → the pressure → one suggestion → closing line.","draft":"Use at least three passives and one non-defining relative clause.","improve":"Replace general adjectives with concrete details; add a concession.","review":"Check that every passive has a clear reason for being passive."}},"lessons":[{"title":"Passive voice: present and past","objective":"Choose the passive when the action, not the doer, carries the message.","canDo":"I can describe places and events with the present and past passive.","skill":"grammar","input":"reading","outputTitle":"Describe your city","output":"Record 60 seconds describing three things that are done in your city every year.","targetSeconds":60},{"title":"Listening: the case for slow travel","objective":"Catch the speaker's opinion and the example that supports it.","canDo":"I can follow a podcast opinion and identify the evidence used to support it.","skill":"listening","input":"listening","outputTitle":"Summarise and react","output":"Summarise the speaker's argument in two sentences and say whether you agree.","wordRange":[50,80]},{"title":"Vocabulary: travel and traditions","objective":"Use ten travel collocations to describe places and behaviour precisely.","canDo":"I can describe a place, its customs and its problems with precise travel vocabulary.","skill":"vocabulary","input":"reading","outputTitle":"Place profile","output":"Record 60 seconds profiling a place using six of the new expressions.","targetSeconds":60},{"title":"Speaking: should tourists follow local customs?","objective":"Take a position, illustrate it and concede the other side in two minutes.","canDo":"I can argue a position on cultural behaviour, concede a point and hold my conclusion.","skill":"speaking","input":"listening","outputTitle":"Two-minute opinion","output":"Use the prompt card: position, two examples, concession.","targetSeconds":120},{"title":"Defining relative clauses","objective":"Identify exactly which person or place you mean without commas.","canDo":"I can define people, places and things precisely with defining relative clauses.","skill":"grammar","input":"reading","outputTitle":"Describe and define","output":"Record six sentences that define places you like using who, which, where and that.","targetSeconds":60},{"title":"Non-defining relative clauses","objective":"Add extra information with correct commas and pronouns.","canDo":"I can add extra information about a place or person without changing the main meaning.","skill":"grammar","input":"listening","outputTitle":"Add the detail","output":"Record five sentences about a city you know, each with one non-defining relative clause.","targetSeconds":60},{"title":"Reading: when tourism becomes too much","objective":"Separate fact, opinion and the writer's concluding question.","canDo":"I can read an article about tourism and distinguish facts from the writer's opinion.","skill":"reading","input":"reading","outputTitle":"Fact or opinion","output":"List three facts and two opinions from the article, then add your own view.","wordRange":[70,100]},{"title":"Writing: descriptive article","objective":"Describe a place and argue for one measure in 160–180 words.","canDo":"I can write a 160–180-word descriptive article that uses the passive and relative clauses.","skill":"writing","input":"reading","outputTitle":"Descriptive article","output":"Draft, then edit for concrete detail and one concession.","wordRange":[160,180]}],"releaseStage":"live"},{"number":4,"title":"Technology and media","summary":"Talk about phones, AI and the news: speculate, report what others said and judge what you read.","hours":8,"vocabularyTopic":"Social media, AI, privacy and misinformation","grammar":[{"key":"modals-of-deduction","name":"Modals of deduction: must, might, could, can't","explanation":"Use must when you are almost certain, might or could when something is possible, and can't when you are almost certain it is untrue.","keyPoints":["Certain: The update must have broken the app.","Possible: She might be working from home.","Impossible: That can't be the reason they cancelled."],"example":"The site is down, so they must be updating the servers; it could also be a network problem.","items":[{"prompt":"The site is down. They ___ be updating the servers.","options":["can't","must","might not"],"answer":"must","explanation":"Must expresses strong certainty based on evidence.","difficulty":1},{"prompt":"That ___ be the reason — the app works fine on other phones.","options":["must","can't","should"],"answer":"can't","explanation":"Can't marks a conclusion you are almost certain is wrong.","difficulty":2},{"prompt":"Which sentence leaves the possibility open?","options":["It must be a bug.","It could be a bug.","It can't be a bug."],"answer":"It could be a bug.","explanation":"Could expresses possibility without certainty.","difficulty":1}]},{"key":"reported-speech","name":"Reported speech and reporting verbs","explanation":"When you report speech, shift the tense back one step and adjust pronouns and time expressions; reporting verbs such as claim, admit and warn change the pattern that follows.","keyPoints":["'I will fix it tomorrow.' → She said she would fix it the next day.","Reporting verb + -ing: He admitted breaking the rules.","Reporting verb + to: They warned us not to share the link."],"example":"The engineer said the update would take two days, admitted that the testing had been rushed, and warned us not to reinstall.","items":[{"prompt":"'I will fix it tomorrow.' → She said she ___ it the next day.","options":["will fix","would fix","fixes"],"answer":"would fix","explanation":"Will shifts to would in reported speech.","difficulty":1},{"prompt":"He admitted ___ the rules.","options":["to break","breaking","break"],"answer":"breaking","explanation":"Admit takes the -ing form.","difficulty":2},{"prompt":"They warned us ___ the link.","options":["not to share","to not share","no sharing"],"answer":"not to share","explanation":"Warn + object + (not) to + infinitive.","difficulty":2}]}],"vocab":[{"term":"algorithm","pos":"noun","definition":"a set of rules a computer follows to choose content","example":"The algorithm shows you what keeps you watching.","collocations":["the recommendation algorithm"],"translation":"algoritmo","audioRef":"module-4/algorithm.mp3"},{"term":"screen time","pos":"noun","definition":"time spent looking at a device","example":"My screen time doubled last month.","collocations":["limit screen time"],"translation":"tiempo de pantalla","audioRef":"module-4/screen-time.mp3"},{"term":"data privacy","pos":"noun","definition":"control over who can see your personal information","example":"Data privacy is the main concern for users.","collocations":["protect data privacy"],"translation":"privacidad de datos","audioRef":"module-4/data-privacy.mp3"},{"term":"misinformation","pos":"noun","definition":"false information spread without intent to deceive","example":"Misinformation travels faster than corrections.","collocations":["spread misinformation"],"translation":"desinformación","audioRef":"module-4/misinformation.mp3"},{"term":"deepfake","pos":"noun","definition":"a video or audio clip generated to look real but false","example":"The deepfake of the mayor was shared thousands of times.","collocations":["a convincing deepfake"],"translation":"ultrafalso","audioRef":"module-4/deepfake.mp3"},{"term":"go viral","pos":"phrase","definition":"spread rapidly online","example":"The clip went viral within hours.","collocations":["go viral overnight"],"translation":"hacerse viral","audioRef":"module-4/go-viral.mp3"},{"term":"clickbait","pos":"noun","definition":"a headline that exaggerates to attract clicks","example":"That headline is pure clickbait.","collocations":["clickbait headlines"],"translation":"cebo de clics","audioRef":"module-4/clickbait.mp3"},{"term":"filter bubble","pos":"noun","definition":"a situation where you only see views like your own","example":"Social feeds can create a filter bubble.","collocations":["live in a filter bubble"],"translation":"burbuja de filtros","audioRef":"module-4/filter-bubble.mp3"},{"term":"digital footprint","pos":"noun","definition":"the trace your online activity leaves","example":"Employers sometimes check your digital footprint.","collocations":["leave a digital footprint"],"translation":"huella digital","audioRef":"module-4/digital-footprint.mp3"},{"term":"scroll through","pos":"phrasal verb","definition":"move quickly through content on a screen","example":"I scrolled through the thread on the train.","collocations":["scroll through your feed"],"translation":"deslizar por","audioRef":"module-4/scroll-through.mp3"}],"inputs":[{"kind":"listening","lesson":2,"title":"Tech news: the week in AI","source":"Studio original — news bulletin","accent":"American","seconds":95,"body":"A major video platform has announced that AI-generated clips must now be labelled. The company said the change would take effect within thirty days and admitted that earlier labelling had been inconsistent. Researchers welcomed the move but warned that labels alone will not stop misinformation, because most people share a clip before they read the caption. One campaign group claimed the policy was 'too little, too late', while the platform insisted that it was a first step.","questions":[{"prompt":"What is the new policy?","options":["AI clips must be labelled","AI clips are banned","All clips must be shorter"],"answer":"AI clips must be labelled"},{"prompt":"What do researchers warn?","options":["Labels are not enough on their own","The policy is too strict","Nobody will notice"],"answer":"Labels are not enough on their own"}],"speaker_accents":[{"speaker":"ANCHOR","accent":"en-US","label":"American"}],"audioRef":"module-4/tech-news-the-week-in-ai.mp3","audioStatus":"actor_pending"},{"kind":"reading","lesson":6,"title":"The price of a free app","source":"Studio original","body":"Nothing on your phone is free. When an app costs nothing to install, the cost is usually paid in attention or data. A typical free app requests access to location, contacts and microphone, and many users accept without reading the prompt. Regulators have begun to push back: several countries now require plain-language summaries of what an app collects. Yet the strongest protection remains unglamorous. Turn off permissions you do not use. Read the prompt. And remember that a service designed to keep you scrolling is not designed to help you leave.","questions":[{"prompt":"What is the writer's main claim?","options":["Free apps are paid for with attention or data","Free apps are always unsafe","Paid apps are always better"],"answer":"Free apps are paid for with attention or data"},{"prompt":"What protection does the writer call strongest?","options":["New regulations","Your own habits and permissions","Deleting all apps"],"answer":"Your own habits and permissions"}],"audioRef":"module-4/the-price-of-a-free-app.mp3","audioStatus":"tts"}],"speaking":[{"kind":"prompt_card","title":"Two-minute opinion: AI and social media","prompt":"Is social media doing more good than harm? Take a position and support it with two examples. Two minutes.","seconds":120,"phrases":["The way I see it...","There is no doubt that...","That said..."],"linkers":["moreover","on the other hand","as a result"],"terms":["filter bubble","misinformation","screen time"]},{"kind":"role_play","title":"Role-play: the privacy conversation","prompt":"A friend wants to install an app that asks for full access to contacts and location. Explain the risks, recommend an alternative and respond to their objections. Two minutes.","seconds":120,"phrases":["I'd be careful about...","Have you considered...?","You might want to..."],"linkers":["because","otherwise","for example"],"terms":["data privacy","digital footprint","permissions"]},{"kind":"shadowing","title":"Shadowing: deduction in connected speech","prompt":"Shadow the clip, noting how must have and might have are reduced to must've and might've.","seconds":60,"phrases":["They must have changed / the settings / without telling anyone."],"linkers":["so","which means","apparently"],"terms":["must have","might have"]}],"writing":{"title":"Review: an app, film or product","prompt":"Write a 180-word review of an app, film or product for a general audience. Describe it, weigh its strengths and weaknesses, and give a clear recommendation.","format":"review","wordMin":170,"wordMax":190,"outline":{"analyze":"Purpose: evaluate and recommend. Audience: potential users or viewers. Register: semi-formal.","plan":"Hook → description → two strengths → one weakness → recommendation.","draft":"Use one modal of deduction and two reported-speech structures.","improve":"Replace vague praise with evidence; vary sentence length.","review":"Check that the recommendation matches the evidence you gave."}},"lessons":[{"title":"Modals of deduction: what must be happening","objective":"Express certainty and possibility about present situations.","canDo":"I can speculate about what is happening using must, might, could and can't.","skill":"grammar","input":"listening","outputTitle":"Diagnose the problem","output":"Listen to three short problems and speculate about the cause of each in 60 seconds.","targetSeconds":60},{"title":"Reported speech: what they said","objective":"Report statements accurately with correct tense shifts and time expressions.","canDo":"I can report what someone said, adjusting tenses, pronouns and time expressions.","skill":"grammar","input":"listening","outputTitle":"Report the bulletin","output":"Report three statements from the tech news bulletin without looking at the transcript.","targetSeconds":90},{"title":"Reporting verbs: claim, admit, warn","objective":"Choose the reporting verb that matches the speaker's attitude and the right pattern.","canDo":"I can summarise what people said using precise reporting verbs.","skill":"grammar","input":"reading","outputTitle":"Retell the argument","output":"Summarise a disagreement you witnessed using claim, admit, warn and deny.","targetSeconds":60},{"title":"Vocabulary: technology and media","objective":"Discuss platforms, AI and privacy with ten precise expressions.","canDo":"I can discuss technology and media issues using topic vocabulary accurately.","skill":"vocabulary","input":"reading","outputTitle":"Tech opinion","output":"Record 60 seconds on one technology you would change, using five new expressions.","targetSeconds":60},{"title":"Listening: the week in AI","objective":"Catch claims, attributions and the difference between what was said and what is true.","canDo":"I can follow a news bulletin and identify who claimed what.","skill":"listening","input":"listening","outputTitle":"Attribution notes","output":"List three claims from the bulletin and who made each one.","wordRange":[50,80]},{"title":"Reading: the price of a free app","objective":"Identify the writer's claim, evidence and recommendation.","canDo":"I can read an opinion article and separate the claim from the practical advice.","skill":"reading","input":"reading","outputTitle":"Claim and advice","output":"Write the claim, one piece of evidence and one piece of advice from the article.","wordRange":[60,90]},{"title":"Speaking: two-minute opinion on AI","objective":"Argue a balanced position and support it with examples in two minutes.","canDo":"I can give a two-minute opinion talk on a technology issue with reasons and examples.","skill":"speaking","input":"listening","outputTitle":"Two-minute opinion talk","output":"Use the prompt card: position, two examples, concession, conclusion.","targetSeconds":120},{"title":"Writing: review of an app or film","objective":"Evaluate a product fairly and recommend it in 180 words.","canDo":"I can write a 180-word review with a balanced evaluation and a clear recommendation.","skill":"writing","input":"reading","outputTitle":"Review","output":"Draft, then edit so each strength has evidence.","wordRange":[170,190]}],"releaseStage":"live"}]} $json$::jsonb) as imported_modules_3_4;

select public.import_modules($json$ {"course_slug":"english-b1-b2","modules":[{"number":5,"title":"Environment and society","summary":"Climate, cities and public services: hypothesise about the past, express regret and propose solutions.","hours":8,"vocabularyTopic":"Climate, sustainability, cities and public services","grammar":[{"key":"third-mixed-conditionals","name":"Third and mixed conditionals","explanation":"The third conditional imagines an unreal past; mixed conditionals connect an unreal past to a present result, or a present state to a past result.","keyPoints":["Third: If the city had invested earlier, the floods would not have been so severe.","Past → present: If I had studied planning, I would be working on this project now.","Present → past: If she were more patient, she would not have quit."],"example":"If the council had built the drainage in 2015, the damage would not be costing us millions now.","items":[{"prompt":"If the city had invested earlier, the floods ___ so severe.","options":["would not be","would not have been","will not be"],"answer":"would not have been","explanation":"Third conditional: had + past participle, would have + past participle.","difficulty":1},{"prompt":"If I had studied planning, I ___ on this project now.","options":["would work","would be working","had worked"],"answer":"would be working","explanation":"Mixed conditional: past cause with a present result.","difficulty":3},{"prompt":"Which sentence blames a past action for a present situation?","options":["If we had acted, the park would be open now.","If we act, the park will open.","If we were acting, the park would be open."],"answer":"If we had acted, the park would be open now.","explanation":"Past perfect in the if-clause plus present result is the mixed pattern.","difficulty":2}]},{"key":"wish-regret","name":"Wish, if only and regret structures","explanation":"Use wish or if only with the past simple for a present regret, with the past perfect for a past regret, and with would to complain about someone else's behaviour.","keyPoints":["Present regret: I wish I lived closer to work.","Past regret: I wish we had started ten years ago.","Complaint: I wish the council would collect the bins on time."],"example":"I wish the city had kept the old tram line; if only we could use it now.","items":[{"prompt":"I wish I ___ closer to work.","options":["live","lived","had lived"],"answer":"lived","explanation":"A present regret takes the past simple after wish.","difficulty":1},{"prompt":"I wish we ___ ten years ago.","options":["started","had started","would start"],"answer":"had started","explanation":"A past regret takes the past perfect after wish.","difficulty":2},{"prompt":"Which sentence complains about someone else's behaviour?","options":["I wish I had a bike.","I wish the council would fix the road.","If only I were taller."],"answer":"I wish the council would fix the road.","explanation":"Wish + would expresses irritation about another person's action.","difficulty":2}]}],"vocab":[{"term":"carbon footprint","pos":"noun","definition":"the amount of carbon dioxide your activity produces","example":"Flying less cut her carbon footprint in half.","collocations":["reduce your carbon footprint"],"translation":"huella de carbono","audioRef":"module-5/carbon-footprint.mp3"},{"term":"renewable energy","pos":"noun","definition":"energy from sources that do not run out","example":"The island runs entirely on renewable energy.","collocations":["invest in renewable energy"],"translation":"energía renovable","audioRef":"module-5/renewable-energy.mp3"},{"term":"sustainable","pos":"adjective","definition":"able to continue without damaging resources","example":"We need a sustainable transport plan, not a short fix.","collocations":["a sustainable solution"],"translation":"sostenible","audioRef":"module-5/sustainable.mp3"},{"term":"urban sprawl","pos":"noun","definition":"the uncontrolled spread of a city into the countryside","example":"Urban sprawl has swallowed the farmland around the city.","collocations":["limit urban sprawl"],"translation":"expansión urbana","audioRef":"module-5/urban-sprawl.mp3"},{"term":"public transport network","pos":"noun","definition":"the system of buses, trains and trams people share","example":"The public transport network is cheap and reliable here.","collocations":["extend the public transport network"],"translation":"red de transporte público","audioRef":"module-5/public-transport-network.mp3"},{"term":"green space","pos":"noun","definition":"parks and other open natural areas in a city","example":"Every district should have green space within ten minutes.","collocations":["protect green space"],"translation":"zona verde","audioRef":"module-5/green-space.mp3"},{"term":"air quality","pos":"noun","definition":"how clean or polluted the air is","example":"Air quality improves when the schools close for summer.","collocations":["poor air quality"],"translation":"calidad del aire","audioRef":"module-5/air-quality.mp3"},{"term":"recycling scheme","pos":"noun","definition":"an organised system for reusing waste","example":"The new recycling scheme covers food waste.","collocations":["introduce a recycling scheme"],"translation":"programa de reciclaje","audioRef":"module-5/recycling-scheme.mp3"},{"term":"climate target","pos":"noun","definition":"a goal for reducing emissions by a set date","example":"The city missed its climate target by two years.","collocations":["meet a climate target"],"translation":"objetivo climático","audioRef":"module-5/climate-target.mp3"},{"term":"take action","pos":"phrase","definition":"do something concrete about a problem","example":"Residents took action before the council did.","collocations":["take urgent action"],"translation":"tomar medidas","audioRef":"module-5/take-action.mp3"}],"inputs":[{"kind":"listening","lesson":5,"title":"Documentary excerpt: the city that cooled itself","source":"Studio original — documentary","accent":"British","seconds":95,"body":"In 2019 this square was a car park. Summer temperatures here were four degrees higher than in the park two streets away, an effect researchers call the urban heat island. The city tried something unfashionable: it planted trees, removed the asphalt and put a small fountain where the delivery vans used to park. Four years later, the temperature difference has almost disappeared. The scheme cost less than one kilometre of road. What surprised the engineers was not the cooling, but how quickly residents started using the space.","questions":[{"prompt":"What was the site before 2019?","options":["A park","A car park","A fountain"],"answer":"A car park"},{"prompt":"What surprised the engineers most?","options":["The cost","How quickly residents used the space","The temperature drop"],"answer":"How quickly residents used the space"}],"speaker_accents":[{"speaker":"NARRATOR","accent":"en-GB","label":"British"}],"audioRef":"module-5/documentary-excerpt-the-city-that-cooled-itself.mp3","audioStatus":"actor_pending"},{"kind":"reading","lesson":6,"title":"Problem, solution: the heat in our streets","source":"Studio original","body":"Cities are hotter than the countryside around them, and the difference is not evenly spread. Districts with fewer trees and more asphalt can be five degrees warmer than wealthier, greener neighbours, which means the people least able to afford air conditioning are the ones who need it most. The solutions are unglamorous and well understood: plant mature trees rather than saplings, replace dark surfaces with reflective ones, and open air-conditioned public buildings during heatwaves. The obstacle is rarely knowledge. It is the budget cycle, which rewards visible new projects over invisible maintenance.","questions":[{"prompt":"Who suffers most from urban heat?","options":["The wealthiest districts","Districts with fewer trees and less money","People in the countryside"],"answer":"Districts with fewer trees and less money"},{"prompt":"What does the writer say is the real obstacle?","options":["Lack of knowledge","Budget priorities","Public opposition"],"answer":"Budget priorities"}],"audioRef":"module-5/problem-solution-the-heat-in-our-streets.mp3","audioStatus":"tts"}],"speaking":[{"kind":"prompt_card","title":"Propose a solution to a local problem","prompt":"Identify one environmental problem in your area and propose a realistic solution. Explain the cost, the benefit and the obstacle. Two minutes.","seconds":120,"phrases":["The problem in my area is...","One solution would be...","The main obstacle is..."],"linkers":["firstly","as a result","however"],"terms":["green space","air quality","take action"]},{"kind":"role_play","title":"Role-play: the council meeting","prompt":"You are presenting a proposal to close a street to traffic. A resident objects. Present the plan, respond to the objection and negotiate one compromise. Two minutes.","seconds":120,"phrases":["I appreciate your concern, but...","Would you be open to...?","What if we...?"],"linkers":["although","on the other hand","in that case"],"terms":["public transport network","urban sprawl","sustainable"]},{"kind":"shadowing","title":"Shadowing: hypothetical past","prompt":"Shadow the clip, keeping the weak forms in would have and had been clear.","seconds":60,"phrases":["If the council / had acted sooner, / we wouldn't have lost / the square."],"linkers":["if","otherwise","as a result"],"terms":["would have","had been"]}],"writing":{"title":"Problem-solution report: a local issue","prompt":"Write a 180–200-word report for a residents' association about one local environmental problem. Describe the problem, analyse two causes, propose two solutions and recommend one.","format":"problem-solution report","wordMin":180,"wordMax":200,"outline":{"analyze":"Purpose: inform and recommend. Audience: residents and local officials. Register: formal, impersonal.","plan":"Problem → causes → solutions → recommendation.","draft":"Use the passive, one third or mixed conditional, and linkers of cause and consequence.","improve":"Replace informal phrasing with impersonal constructions; add figures or comparisons.","review":"Check that each solution answers one of the causes you described."}},"lessons":[{"title":"Third conditional: the past we did not have","objective":"Imagine alternative past outcomes and their consequences.","canDo":"I can discuss how a past decision could have produced a different result.","skill":"grammar","input":"reading","outputTitle":"What if","output":"Record five third-conditional sentences about a decision your city or company made.","targetSeconds":60},{"title":"Mixed conditionals: past cause, present result","objective":"Connect an unreal past to a present situation and vice versa.","canDo":"I can link a past decision to a present consequence in one sentence.","skill":"grammar","input":"listening","outputTitle":"Cause and effect","output":"Record four mixed conditionals about the environment or your own life.","targetSeconds":60},{"title":"Wish and if only: expressing regret","objective":"Express present and past regrets and complaints with the right structure.","canDo":"I can express regret about the past and irritation about the present.","skill":"grammar","input":"reading","outputTitle":"Regrets","output":"Record five sentences with wish and if only about your city or your studies.","targetSeconds":60},{"title":"Vocabulary: environment and cities","objective":"Discuss climate and urban issues with ten precise expressions.","canDo":"I can describe environmental and urban problems with topic vocabulary.","skill":"vocabulary","input":"reading","outputTitle":"My area","output":"Record 60 seconds describing your area using six new expressions.","targetSeconds":60},{"title":"Listening: the city that cooled itself","objective":"Follow a documentary extract and catch cause, effect and evaluation.","canDo":"I can follow a documentary extract and separate facts from the speaker's evaluation.","skill":"listening","input":"listening","outputTitle":"Note and evaluate","output":"Note three facts and one evaluation from the documentary extract.","wordRange":[50,80]},{"title":"Reading: the heat in our streets","objective":"Map a problem-solution text: problem, causes, solutions, obstacle.","canDo":"I can read a problem-solution article and reconstruct its argument structure.","skill":"reading","input":"reading","outputTitle":"Structure map","output":"Write the problem, two causes, two solutions and the obstacle in the article.","wordRange":[70,100]},{"title":"Speaking: proposing a solution","objective":"Present a proposal with cost, benefit and obstacle in two minutes.","canDo":"I can propose a realistic solution and anticipate the main objection.","skill":"speaking","input":"listening","outputTitle":"Two-minute proposal","output":"Use the prompt card: problem, solution, cost, obstacle.","targetSeconds":120},{"title":"Writing: problem-solution report","objective":"Write a structured formal report of 180–200 words.","canDo":"I can write a formal problem-solution report with causes, solutions and a recommendation.","skill":"writing","input":"reading","outputTitle":"Report","output":"Draft, then edit for impersonal register and clear cause-effect links.","wordRange":[180,200]}],"releaseStage":"live"},{"number":6,"title":"Health and ethics","summary":"Lifestyle, choice and responsibility: arrange services, weigh arguments and write a formal essay.","hours":8,"vocabularyTopic":"Health, lifestyle, ethics and consumer choices","grammar":[{"key":"causatives","name":"Causatives: have / get something done","explanation":"Use have or get something done when someone else performs a service for you, and have someone do something when you arrange it directly.","keyPoints":["Service: I had my blood pressure checked last week.","Arrangement: She got the pharmacy to deliver the prescription.","Trouble: He had his appendix removed on Monday."],"example":"I had my eyes tested on Friday and got the optician to adjust the lenses for free.","items":[{"prompt":"I ___ my blood pressure checked last week.","options":["checked","had","did checked"],"answer":"had","explanation":"Have + object + past participle shows a service performed by someone else.","difficulty":1},{"prompt":"Which sentence means someone else did the work?","options":["I repaired my bike.","I had my bike repaired.","I was repairing my bike."],"answer":"I had my bike repaired.","explanation":"The causative makes the agent of the action someone other than the subject.","difficulty":2},{"prompt":"She ___ the pharmacy to deliver the prescription.","options":["had","got","made"],"answer":"got","explanation":"Get + person + to + infinitive describes persuading or arranging.","difficulty":3}]},{"key":"advanced-linkers","name":"Advanced linkers: whereas, consequently, nevertheless, in spite of","explanation":"Advanced writing needs linkers that signal contrast, consequence and concession precisely, with the right grammar after each one.","keyPoints":["Contrast between clauses: Whereas the tax raised revenue, it hit low earners hardest.","Consequence: Consequently, consumption fell by eighteen per cent.","Concession: Nevertheless, the measure remains controversial. / In spite of the criticism, it stayed."],"example":"Whereas the levy reduced consumption, it was criticised as regressive; nevertheless, the government has kept it, in spite of two legal challenges.","items":[{"prompt":"___ the tax raised revenue, it hit low earners hardest.","options":["Whereas","Nevertheless","Consequently"],"answer":"Whereas","explanation":"Whereas introduces a direct contrast between two clauses.","difficulty":1},{"prompt":"Consumption fell sharply; ___, revenue also dropped.","options":["consequently","whereas","in spite of"],"answer":"consequently","explanation":"Consequently marks a result of the previous statement.","difficulty":1},{"prompt":"___ the criticism, the policy remained in place.","options":["In spite of","Whereas","Consequently"],"answer":"In spite of","explanation":"In spite of + noun phrase expresses concession.","difficulty":2}]}],"vocab":[{"term":"balanced diet","pos":"noun","definition":"a way of eating with the right variety of nutrients","example":"A balanced diet matters more than any single superfood.","collocations":["maintain a balanced diet"],"translation":"dieta equilibrada","audioRef":"module-6/balanced-diet.mp3"},{"term":"sedentary lifestyle","pos":"noun","definition":"a way of living with very little physical activity","example":"A sedentary lifestyle raises the risk of heart disease.","collocations":["lead a sedentary lifestyle"],"translation":"estilo de vida sedentario","audioRef":"module-6/sedentary-lifestyle.mp3"},{"term":"mental wellbeing","pos":"noun","definition":"the state of feeling psychologically healthy","example":"Sleep affects mental wellbeing more than most people realise.","collocations":["support mental wellbeing"],"translation":"bienestar mental","audioRef":"module-6/mental-wellbeing.mp3"},{"term":"cut down on","pos":"phrasal verb","definition":"reduce the amount you consume","example":"I am cutting down on sugary drinks.","collocations":["cut down on sugar"],"translation":"reducir el consumo de","audioRef":"module-6/cut-down-on.mp3"},{"term":"addictive","pos":"adjective","definition":"difficult to stop doing or consuming","example":"Highly processed food is designed to be addictive.","collocations":["highly addictive"],"translation":"adictivo","audioRef":"module-6/addictive.mp3"},{"term":"ethical","pos":"adjective","definition":"morally right or acceptable","example":"Is it ethical to advertise junk food to children?","collocations":["an ethical question"],"translation":"ético","audioRef":"module-6/ethical.mp3"},{"term":"consumer choice","pos":"noun","definition":"the freedom to decide what to buy","example":"Taxes are meant to shape consumer choice, not punish it.","collocations":["restrict consumer choice"],"translation":"elección del consumidor","audioRef":"module-6/consumer-choice.mp3"},{"term":"fair trade","pos":"noun","definition":"trade that pays producers a fair price","example":"The café only sells fair trade coffee.","collocations":["fair trade products"],"translation":"comercio justo","audioRef":"module-6/fair-trade.mp3"},{"term":"sugary drinks","pos":"noun","definition":"beverages with a high sugar content","example":"Several cities now tax sugary drinks.","collocations":["a tax on sugary drinks"],"translation":"bebidas azucaradas","audioRef":"module-6/sugary-drinks.mp3"},{"term":"public health","pos":"noun","definition":"the health of a whole population, and the policy around it","example":"Public health experts welcomed the measure.","collocations":["a public health measure"],"translation":"salud pública","audioRef":"module-6/public-health.mp3"}],"inputs":[{"kind":"reading","lesson":5,"title":"Should junk food be taxed? Two views","source":"Studio original — opinion page","body":"FOR: The case is straightforward. Sugar taxes reduce consumption, and consumption of sugar raises the risk of diseases that cost public health systems billions. A levy of ten per cent in one European country cut purchases of sugary drinks by eighteen per cent within a year, and the revenue funded free school meals. AGAINST: The case is equally straightforward. Such taxes are regressive: they take a larger share of income from poorer households, who also have less time to cook and fewer affordable alternatives. Education and better labelling would achieve more, and would not punish people for buying what is cheapest.","questions":[{"prompt":"What evidence supports the tax?","options":["An eighteen per cent drop in purchases","Higher employment","Lower food prices"],"answer":"An eighteen per cent drop in purchases"},{"prompt":"What is the main objection?","options":["The tax is regressive","The tax is too low","The tax is illegal"],"answer":"The tax is regressive"}],"audioRef":"module-6/should-junk-food-be-taxed-two-views.mp3","audioStatus":"tts"},{"kind":"listening","lesson":6,"title":"Panel discussion: whose responsibility is health?","source":"Studio original — panel discussion","accent":"British and South African","seconds":100,"body":"CHAIR: Whose responsibility is health? DR OSEI: I get uncomfortable when we talk only about individual choice, because choice is shaped. If the only shop within a kilometre sells processed food, that is not a free choice. DR LEWIS: I agree up to a point, but people do respond to information. Smoking fell for decades before any ban, largely because attitudes changed. CHAIR: So is taxation part of the answer? DR OSEI: It can be, provided the revenue goes back into prevention. Otherwise it just looks like a fine on being poor.","questions":[{"prompt":"Why does Dr Osei distrust the 'individual choice' argument?","options":["Because choice is shaped by the environment","Because people are irresponsible","Because taxation never works"],"answer":"Because choice is shaped by the environment"},{"prompt":"What condition does Dr Osei set for taxation?","options":["Revenue must fund prevention","It must apply only to the rich","It must be temporary"],"answer":"Revenue must fund prevention"}],"speaker_accents":[{"speaker":"CHAIR","accent":"en-GB","label":"British"},{"speaker":"DR OSEI","accent":"en-ZA","label":"South African"},{"speaker":"DR LEWIS","accent":"en-GB","label":"British"}],"audioRef":"module-6/panel-discussion-whose-responsibility-is-health.mp3","audioStatus":"actor_pending"}],"speaking":[{"kind":"prompt_card","title":"Debate: should junk food be taxed?","prompt":"Argue either for or against a tax on junk food. Use two pieces of evidence, address the strongest objection and conclude. Two to three minutes.","seconds":150,"phrases":["The evidence suggests...","The strongest objection is...","On balance, I would argue..."],"linkers":["whereas","nevertheless","consequently"],"terms":["public health","consumer choice","regressive"]},{"kind":"role_play","title":"Role-play: the doctor's appointment","prompt":"You are explaining a change in your lifestyle to a doctor. Describe your habits, ask about two treatments, and agree on one plan. Two minutes.","seconds":120,"phrases":["I've been feeling...","I was wondering whether...","I'll try to..."],"linkers":["because","so that","even though"],"terms":["sedentary lifestyle","cut down on","mental wellbeing"]},{"kind":"shadowing","title":"Shadowing: concession and consequence","prompt":"Shadow the clip, marking the pause after Nevertheless and the stress on Whereas.","seconds":60,"phrases":["Whereas the tax raised revenue, / it hit low earners hardest. / Nevertheless, / it stayed."],"linkers":["whereas","nevertheless","in spite of"],"terms":["consequently","regressive"]}],"writing":{"title":"Argument essay: health and responsibility","prompt":"Write a 200-word argument essay: should governments tax unhealthy products to improve public health? Present both sides and reach a clear conclusion.","format":"argument essay","wordMin":195,"wordMax":215,"outline":{"analyze":"Purpose: argue and conclude. Audience: an examiner or opinion page. Register: formal.","plan":"Introduction with position → argument for → argument against → evaluation → conclusion.","draft":"Use at least three advanced linkers and one causative structure.","improve":"Qualify your claims; replace absolutes with hedging where evidence is limited.","review":"Check that the conclusion follows from the evaluation, not from repetition."}},"lessons":[{"title":"Causatives: have and get something done","objective":"Describe services and arrangements with have/get + object + past participle.","canDo":"I can talk about services I arrange for other people to do.","skill":"grammar","input":"reading","outputTitle":"Things I arranged","output":"Record five sentences about services you have had done this year.","targetSeconds":60},{"title":"Linkers of contrast and consequence","objective":"Use whereas, consequently and related linkers with correct punctuation and grammar.","canDo":"I can contrast two ideas and state a consequence precisely in writing.","skill":"grammar","input":"reading","outputTitle":"Two sides","output":"Write four sentences contrasting two habits or policies, using whereas and consequently.","wordRange":[60,90]},{"title":"Linkers of concession: nevertheless, in spite of","objective":"Concede a point without weakening your argument.","canDo":"I can concede a valid objection and still defend my position.","skill":"grammar","input":"listening","outputTitle":"Concede and defend","output":"Record four sentences that concede a point and then defend a position.","targetSeconds":60},{"title":"Vocabulary: health and ethics","objective":"Discuss lifestyle, choice and responsibility with ten precise expressions.","canDo":"I can discuss health and consumer ethics using topic vocabulary accurately.","skill":"vocabulary","input":"reading","outputTitle":"Health opinion","output":"Record 60 seconds on one health habit you would change, using five new expressions.","targetSeconds":60},{"title":"Reading: should junk food be taxed?","objective":"Compare two opposed arguments and identify the evidence used by each.","canDo":"I can read two opposing arguments and summarise the evidence on both sides.","skill":"reading","input":"reading","outputTitle":"Two-column summary","output":"Write two columns: the strongest point and the weakest point of each side.","wordRange":[70,100]},{"title":"Listening: whose responsibility is health?","objective":"Follow a panel discussion and track who holds which position.","canDo":"I can follow a panel discussion and identify each speaker's position and condition.","skill":"listening","input":"listening","outputTitle":"Positions map","output":"Note each speaker's position in one sentence, plus one condition they set.","wordRange":[50,80]},{"title":"Speaking: the junk food debate","objective":"Argue a contested position, handle the strongest objection and conclude.","canDo":"I can debate a public health question for two to three minutes with evidence and concession.","skill":"speaking","input":"listening","outputTitle":"Two-minute debate","output":"Use the prompt card: position, evidence, objection, conclusion.","targetSeconds":150},{"title":"Writing: argument essay","objective":"Plan and write a balanced 200-word essay with a reasoned conclusion.","canDo":"I can write a 200-word argument essay that evaluates both sides and concludes clearly.","skill":"writing","input":"reading","outputTitle":"Argument essay","output":"Draft, then edit for hedging and linkers.","wordRange":[195,215]}],"releaseStage":"live"}]} $json$::jsonb) as imported_modules_5_6;

select public.import_modules($json$ {"course_slug":"english-b1-b2","modules":[{"number":7,"title":"Persuasion and debate","summary":"Argue under pressure: emphasise with inversion, hedge with precision and rebut without hostility.","hours":8,"vocabularyTopic":"Persuasion, evidence, policy and disagreement","grammar":[{"key":"inversion-emphasis","name":"Inversion for emphasis: Not only…, Rarely…","explanation":"After a negative or limiting adverbial at the start of a sentence, invert the subject and auxiliary to add emphasis.","keyPoints":["Not only did the policy cut emissions, but it also created jobs.","Rarely have I seen such a weak argument.","Never before has the city faced this choice. / Little did we know…"],"example":"Not only did the levy reduce consumption, but it also funded school meals; rarely has a policy faced such organised opposition.","items":[{"prompt":"Not only ___ the policy cut emissions, but it also created jobs.","options":["did","has","did it"],"answer":"did","explanation":"Not only + auxiliary + subject + verb: Not only did the policy cut emissions…","difficulty":2},{"prompt":"Rarely ___ such a weak argument.","options":["I have heard","have I heard","I heard"],"answer":"have I heard","explanation":"A fronted negative adverbial triggers inversion: Rarely have I heard…","difficulty":2},{"prompt":"Which sentence is correctly inverted?","options":["Never the city has faced this choice.","Never has the city faced this choice.","Never has faced the city this choice."],"answer":"Never has the city faced this choice.","explanation":"Auxiliary before subject, then the main verb.","difficulty":3}]},{"key":"hedging","name":"Hedging: It appears that…, This may suggest…","explanation":"Hedging shows how confident you are, protects you from overclaiming and makes debate sound reasonable rather than dogmatic.","keyPoints":["It appears that the data supports the claim, although further study is needed.","This may suggest a link between the two, rather than prove one.","Use tend to, arguably, to some extent and it is likely that to soften claims."],"example":"The figures appear to support the tax, although they may also reflect a broader change in buying habits.","items":[{"prompt":"Which sentence is best hedged for an academic essay?","options":["Sugar taxes definitely work.","The evidence suggests that sugar taxes tend to reduce consumption.","Everyone knows sugar taxes work."],"answer":"The evidence suggests that sugar taxes tend to reduce consumption.","explanation":"Suggests and tend to signal limited confidence without weakening the point.","difficulty":1},{"prompt":"This ___ suggest a link, but it does not prove one.","options":["may","must","will"],"answer":"may","explanation":"May expresses possibility and keeps the claim proportionate.","difficulty":1},{"prompt":"Which phrase overclaims?","options":["It is likely that...","This arguably shows...","This proves beyond doubt..."],"answer":"This proves beyond doubt...","explanation":"Beyond doubt is an absolute claim, the opposite of hedging.","difficulty":2}]}],"vocab":[{"term":"persuasive","pos":"adjective","definition":"able to convince people to agree","example":"Her closing argument was quietly persuasive.","collocations":["a persuasive argument"],"translation":"persuasivo","audioRef":"module-7/persuasive.mp3"},{"term":"compelling evidence","pos":"noun","definition":"evidence strong enough to convince","example":"There is compelling evidence that the scheme works.","collocations":["provide compelling evidence"],"translation":"pruebas convincentes","audioRef":"module-7/compelling-evidence.mp3"},{"term":"counter-argument","pos":"noun","definition":"a reason against a position","example":"He answered the counter-argument before it was raised.","collocations":["address the counter-argument"],"translation":"contraargumento","audioRef":"module-7/counter-argument.mp3"},{"term":"concede a point","pos":"phrase","definition":"admit that the other side is partly right","example":"I concede the point about cost, but not about fairness.","collocations":["willing to concede a point"],"translation":"conceder un punto","audioRef":"module-7/concede-a-point.mp3"},{"term":"policy proposal","pos":"noun","definition":"a suggested plan of action for an organisation","example":"The policy proposal goes to the committee in May.","collocations":["draft a policy proposal"],"translation":"propuesta política","audioRef":"module-7/policy-proposal.mp3"},{"term":"common ground","pos":"noun","definition":"shared opinions or interests","example":"We found common ground on transport.","collocations":["find common ground"],"translation":"terreno común","audioRef":"module-7/common-ground.mp3"},{"term":"weak argument","pos":"noun","definition":"a reason that does not convince","example":"Saying 'it has always been like this' is a weak argument.","collocations":["a fundamentally weak argument"],"translation":"argumento débil","audioRef":"module-7/weak-argument.mp3"},{"term":"rebut","pos":"verb","definition":"answer an argument with evidence or reasoning","example":"She rebutted the claim in two sentences.","collocations":["rebut a claim"],"translation":"refutar","audioRef":"module-7/rebut.mp3"},{"term":"credibility","pos":"noun","definition":"the quality of being believed or trusted","example":"Overstating the case costs you credibility.","collocations":["lose credibility"],"translation":"credibilidad","audioRef":"module-7/credibility.mp3"},{"term":"call for action","pos":"noun","definition":"a public demand that something be done","example":"The report ends with a call for action on air quality.","collocations":["an urgent call for action"],"translation":"llamada a la acción","audioRef":"module-7/call-for-action.mp3"}],"inputs":[{"kind":"listening","lesson":4,"title":"Panel debate: should cities ban cars from the centre?","source":"Studio original — panel discussion","accent":"British and American","seconds":105,"body":"HOST: Is a car-free centre realistic? COUNCILLOR REID: Not only has it worked elsewhere, but it has also increased footfall in the shops. That is the part people miss. TRADER MS KOVAC: With respect, that has not been our experience. Our deliveries arrive before seven, and the loading bay is gone. COUNCILLOR REID: Then let us concede that point and solve it — timed access. MS KOVAC: I would accept timed access, provided it is enforced. My worry is that it looks good in a report and fails in the street.","questions":[{"prompt":"What does Councillor Reid claim about shops?","options":["Footfall increased elsewhere","Shops closed","Deliveries stopped"],"answer":"Footfall increased elsewhere"},{"prompt":"What does Ms Kovac accept in the end?","options":["Timed access with enforcement","A total ban","No change at all"],"answer":"Timed access with enforcement"}],"speaker_accents":[{"speaker":"HOST","accent":"en-GB","label":"British"},{"speaker":"COUNCILLOR REID","accent":"en-GB","label":"British"},{"speaker":"MS KOVAC","accent":"en-US","label":"American"}],"audioRef":"module-7/panel-debate-should-cities-ban-cars-from-the-centre.mp3","audioStatus":"actor_pending"},{"kind":"reading","lesson":5,"title":"How to write a proposal that gets read","source":"Studio original","body":"Most proposals fail for a boring reason: the reader cannot find the recommendation. A useful proposal opens with the decision required, not with background. It states the problem in one paragraph, the options in three, and the recommendation in one sentence that could be quoted. Evidence should be proportionate: two strong figures persuade more than ten weak ones. Finally, anticipate the objection your reader will raise and answer it on the page, in their words. Not only does this show respect, but it also removes the easiest reason to say no.","questions":[{"prompt":"What should a proposal open with?","options":["The decision required","Long background","A list of sources"],"answer":"The decision required"},{"prompt":"What does the writer advise about evidence?","options":["Use two strong figures","Include everything","Avoid figures"],"answer":"Use two strong figures"}],"audioRef":"module-7/how-to-write-a-proposal-that-gets-read.mp3","audioStatus":"tts"}],"speaking":[{"kind":"prompt_card","title":"Three-minute persuasive monologue and rebuttal","prompt":"Choose a policy you would change. Present it in two minutes, then respond to a counter-argument read aloud in the third minute.","seconds":180,"phrases":["Not only does this..., but it also...","It appears that...","I would concede that..., however..."],"linkers":["moreover","nevertheless","in other words"],"terms":["policy proposal","compelling evidence","counter-argument"]},{"kind":"role_play","title":"Role-play: negotiating with an opponent","prompt":"You are negotiating a joint statement with someone who opposes your position. Find common ground, concede one point and secure one commitment. Two to three minutes.","seconds":150,"phrases":["Could we agree that...?","I take your point about...","What would you need in return?"],"linkers":["provided that","on condition that","whereas"],"terms":["common ground","concede a point","credibility"]},{"kind":"shadowing","title":"Shadowing: inversion under pressure","prompt":"Shadow the clip, keeping the falling intonation on the inverted clause and the pause before the rebuttal.","seconds":60,"phrases":["Not only did the policy work, / but it also / won over its critics."],"linkers":["not only","rarely","little"],"terms":["rebut","weak argument"]}],"writing":{"title":"Formal proposal: a change worth making","prompt":"Write a 180–200-word formal proposal to a decision-maker recommending one change to a policy you know. Include the decision required, the options and a clear recommendation.","format":"formal proposal","wordMin":180,"wordMax":200,"outline":{"analyze":"Purpose: secure a decision. Audience: a busy official. Register: formal and direct.","plan":"Decision required → problem → three options → recommendation → one anticipated objection.","draft":"Use one inversion, two hedges and a conditional offer (provided that).","improve":"Cut background; make the recommendation quotable in one sentence.","review":"Check that a reader could act on the proposal after one reading."}},"lessons":[{"title":"Inversion for emphasis","objective":"Front a negative adverbial and invert the subject and auxiliary correctly.","canDo":"I can add emphasis with Not only, Rarely and Little did without breaking word order.","skill":"grammar","input":"listening","outputTitle":"Emphasise it","output":"Record five sentences using inversion to emphasise a real opinion.","targetSeconds":60},{"title":"Hedging: saying it without overclaiming","objective":"Calibrate certainty with it appears that, may suggest and tend to.","canDo":"I can express confidence at the right level instead of overclaiming.","skill":"grammar","input":"reading","outputTitle":"Hedge the claim","output":"Take five strong claims and rewrite each one with appropriate hedging.","wordRange":[60,90]},{"title":"Vocabulary: persuasion and evidence","objective":"Debate with ten precise expressions for arguments, evidence and concessions.","canDo":"I can name the parts of an argument and evaluate evidence precisely.","skill":"vocabulary","input":"reading","outputTitle":"Weigh the argument","output":"Record 60 seconds evaluating an argument you have heard recently.","targetSeconds":60},{"title":"Listening: should cities ban cars?","objective":"Track positions, concessions and conditions across a heated panel.","canDo":"I can follow a panel debate and note who conceded what and on which condition.","skill":"listening","input":"listening","outputTitle":"Position and concession","output":"Note each speaker's position, one concession and one condition.","wordRange":[50,80]},{"title":"Reading: writing a proposal that gets read","objective":"Extract the recommended structure and the writer's advice on evidence.","canDo":"I can read advice on formal writing and apply its structure to my own proposal.","skill":"reading","input":"reading","outputTitle":"Structure checklist","output":"Turn the article into a five-point checklist for your own proposal.","wordRange":[60,90]},{"title":"Speaking: persuade, then rebut","objective":"Deliver a three-minute persuasive case and answer a counter-argument.","canDo":"I can present a persuasive case and rebut an objection without losing composure.","skill":"speaking","input":"listening","outputTitle":"Monologue plus rebuttal","output":"Use the prompt card: two minutes of argument, one minute of rebuttal.","targetSeconds":180},{"title":"Writing: formal proposal","objective":"Write a decision-ready proposal of 180–200 words.","canDo":"I can write a formal proposal with a clear recommendation and an anticipated objection.","skill":"writing","input":"reading","outputTitle":"Proposal","output":"Draft, then cut every sentence that does not serve the decision.","wordRange":[180,200]},{"title":"Review: timed interactive discussion","objective":"Sustain a ten-minute discussion with a partner, using the module's tools under pressure.","canDo":"I can hold my own in a ten-minute discussion, hedging, conceding and rebutting appropriately.","skill":"review","input":"listening","outputTitle":"Discussion simulation","output":"Record a ten-minute simulation: present, respond, concede and conclude.","targetSeconds":600}],"releaseStage":"live"},{"number":8,"title":"B2 consolidation","summary":"Pull it together: mixed-skill practice under time pressure, then the final B2 assessment.","hours":8,"vocabularyTopic":"High-value B2 lexis for argument and evaluation","grammar":[{"key":"review-perfect-aspects","name":"Review: perfect and narrative aspects","explanation":"B2 accuracy in the perfect family comes from choosing by meaning: present perfect for relevance now, past perfect for a prior past point, and perfect continuous for duration.","keyPoints":["Relevance now: I have been working on this since March.","Prior past: By the time the study was published, the policy had already changed.","Duration before a past point: They had been negotiating for months."],"example":"I have been studying for two years, and by the time I finish, I will have completed eleven courses.","items":[{"prompt":"I ___ on this since March.","options":["work","have been working","had worked"],"answer":"have been working","explanation":"Since + a point in time with an ongoing activity requires the present perfect continuous.","difficulty":1},{"prompt":"By the time the study was published, the policy ___.","options":["already changed","had already changed","has already changed"],"answer":"had already changed","explanation":"The change happened before a past publication, so the past perfect is required.","difficulty":2},{"prompt":"They ___ for months before the agreement was signed.","options":["negotiated","had been negotiating","have negotiated"],"answer":"had been negotiating","explanation":"Duration before a past event takes the past perfect continuous.","difficulty":2}]},{"key":"review-modals-reported","name":"Review: conditionals, modals and reported speech","explanation":"At B2 these systems are combined: conditionals carry modal meaning, modality shifts in reported speech, and hedging keeps claims proportionate.","keyPoints":["Had they consulted residents, the plan would have passed.","She said it might have been avoided if the notice had been longer.","It may be that the figures understate the effect."],"example":"Had the consultation been longer, the council might not have lost the vote; several members said they would have supported a revised plan.","items":[{"prompt":"___ they consulted residents, the plan would have passed.","options":["Had","If","Have"],"answer":"Had","explanation":"Inverted third conditional: Had + subject + past participle.","difficulty":3},{"prompt":"She said it ___ if the notice had been longer.","options":["might have been avoided","might be avoided","might avoid"],"answer":"might have been avoided","explanation":"Reported past possibility with a passive: might have been avoided.","difficulty":3},{"prompt":"Which sentence is the most cautious?","options":["The figures understate the effect.","The figures may understate the effect.","The figures definitely understate the effect."],"answer":"The figures may understate the effect.","explanation":"May keeps the claim provisional, which is the safest B2 academic choice.","difficulty":1}]}],"vocab":[{"term":"outweigh","pos":"verb","definition":"be more important than something else","example":"The benefits outweigh the costs in the long run.","collocations":["benefits outweigh the risks"],"translation":"superar en importancia","audioRef":"module-8/outweigh.mp3"},{"term":"inevitable","pos":"adjective","definition":"certain to happen and impossible to avoid","example":"Some disruption is inevitable during the works.","collocations":["a seemingly inevitable outcome"],"translation":"inevitable","audioRef":"module-8/inevitable.mp3"},{"term":"mitigate","pos":"verb","definition":"reduce the harmful effects of something","example":"Trees mitigate the heat in dense districts.","collocations":["mitigate the impact"],"translation":"mitigar","audioRef":"module-8/mitigate.mp3"},{"term":"prevalent","pos":"adjective","definition":"common in a particular place or time","example":"The practice is most prevalent in coastal towns.","collocations":["increasingly prevalent"],"translation":"predominante","audioRef":"module-8/prevalent.mp3"},{"term":"contend","pos":"verb","definition":"argue that something is true","example":"Critics contend that the figures are incomplete.","collocations":["critics contend that"],"translation":"sostener, afirmar","audioRef":"module-8/contend.mp3"},{"term":"detrimental","pos":"adjective","definition":"causing harm","example":"Long commutes are detrimental to health.","collocations":["detrimental to wellbeing"],"translation":"perjudicial","audioRef":"module-8/detrimental.mp3"},{"term":"feasible","pos":"adjective","definition":"possible and practical to do","example":"A partial ban is feasible within a year.","collocations":["technically feasible"],"translation":"viable","audioRef":"module-8/feasible.mp3"},{"term":"consensus","pos":"noun","definition":"general agreement among a group","example":"There is broad consensus on the diagnosis, not the cure.","collocations":["reach a consensus"],"translation":"consenso","audioRef":"module-8/consensus.mp3"},{"term":"nuance","pos":"noun","definition":"a small but important difference in meaning","example":"The argument ignores an important nuance.","collocations":["lose the nuance"],"translation":"matiz","audioRef":"module-8/nuance.mp3"},{"term":"deteriorate","pos":"verb","definition":"become worse over time","example":"Air quality deteriorated after the roads reopened.","collocations":["conditions deteriorate"],"translation":"deteriorarse","audioRef":"module-8/deteriorate.mp3"}],"inputs":[{"kind":"listening","lesson":4,"title":"Timed listening: three accents, one topic","source":"Studio original — mixed accents","accent":"British, Nigerian and Indian","seconds":110,"body":"SPEAKER 1: I grew up in a city where nobody cycled, and now there are more bikes than cars on my old street. SPEAKER 2: The infrastructure came first, which is the opposite of what most cities try. You cannot ask people to change and then blame them when there is nowhere safe to go. SPEAKER 3: What interests me is the budget. Cycle lanes are cheap compared with a motorway, yet they are treated as a luxury. If the same money had gone into roads, nobody would have questioned it.","questions":[{"prompt":"What does Speaker 2 say cities usually do wrong?","options":["Build infrastructure after asking people to change","Ignore their residents","Spend too much on bikes"],"answer":"Build infrastructure after asking people to change"},{"prompt":"What surprises Speaker 3?","options":["Cycle lanes are treated as a luxury","Roads are expensive","Nobody cycles"],"answer":"Cycle lanes are treated as a luxury"}],"speaker_accents":[{"speaker":"SPEAKER 1","accent":"en-GB","label":"British"},{"speaker":"SPEAKER 2","accent":"en-NG","label":"Nigerian"},{"speaker":"SPEAKER 3","accent":"en-IN","label":"Indian"}],"audioRef":"module-8/timed-listening-three-accents-one-topic.mp3","audioStatus":"actor_pending"},{"kind":"reading","lesson":6,"title":"Timed reading: the limits of a good statistic","source":"Studio original","body":"A single impressive number can end a discussion before it starts, which is precisely why it deserves suspicion. Take the claim that a policy 'created ten thousand jobs'. The figure may be accurate and still misleading: it says nothing about whether those jobs replaced others, how long they lasted, or who got them. Serious evaluation asks for the counterfactual — what would have happened anyway — and that is the question a headline rarely answers. Readers who learn to ask it become considerably harder to persuade with a number alone.","questions":[{"prompt":"Why does the writer distrust impressive numbers?","options":["They can be accurate yet misleading","They are usually false","They are hard to read"],"answer":"They can be accurate yet misleading"},{"prompt":"What question does serious evaluation ask?","options":["What would have happened anyway?","Who paid for the study?","How was it reported?"],"answer":"What would have happened anyway?"}],"audioRef":"module-8/timed-reading-the-limits-of-a-good-statistic.mp3","audioStatus":"tts"}],"speaking":[{"kind":"monologue","title":"Final speaking: three-minute opinion talk","prompt":"Some people believe remote work improves productivity. Do you agree? Give reasons and examples. Speak for three minutes using at least three linking expressions and two topic-specific terms.","seconds":180,"phrases":["On balance...","The evidence suggests...","A good illustration of this is..."],"linkers":["moreover","whereas","as a result","nevertheless"],"terms":["productivity","consolidation","consensus"]},{"kind":"interview","title":"Speaking interview: follow-up questions","prompt":"Answer three follow-up questions on your talk: one asking for evidence, one challenging your position, one asking for a prediction.","seconds":120,"phrases":["That is a fair challenge...","I would qualify that by saying...","Looking ahead, I expect..."],"linkers":["although","in particular","by contrast"],"terms":["nuance","feasible","mitigate"]},{"kind":"shadowing","title":"Shadowing: B2 prosody capstone","prompt":"Shadow the model twice: stress the contrast, chunk the thought groups and keep the intonation falling on statements.","seconds":90,"phrases":["What matters / is not how fast you speak, / but how clearly / you are understood."],"linkers":["not... but","rather than","in fact"],"terms":["intelligibility","prosody"]}],"writing":{"title":"Final essay: an argument with examples","prompt":"Write a 200–220-word argument essay: is remote work better for productivity and wellbeing? Present both sides, use evidence, and reach a clear conclusion.","format":"argument essay","wordMin":200,"wordMax":220,"outline":{"analyze":"Purpose: argue and conclude. Audience: an examiner. Register: formal.","plan":"Introduction with position → for → against → evaluation → conclusion.","draft":"Use one inversion, two hedges, two advanced linkers and one conditional.","improve":"Replace generic claims with qualified ones; add one concrete example.","review":"Check the essay answers the question, not merely the topic."}},"lessons":[{"title":"Review: perfect and narrative aspects","objective":"Choose accurately across the perfect family in extended speech.","canDo":"I can use perfect and narrative aspects accurately when I speak at length.","skill":"grammar","input":"listening","outputTitle":"My last two years","output":"Record 90 seconds on your last two years using four perfect forms.","targetSeconds":90},{"title":"Review: conditionals, modals and reported speech","objective":"Combine conditionals, modality and reported speech without losing accuracy.","canDo":"I can combine conditionals and reported speech accurately in a complex sentence.","skill":"grammar","input":"reading","outputTitle":"Complex sentence drill","output":"Write and record five complex sentences joining a conditional to reported speech.","targetSeconds":90},{"title":"Review: modals of deduction and hedging","objective":"Calibrate certainty across a long answer.","canDo":"I can express certainty, possibility and doubt precisely across a long turn.","skill":"grammar","input":"listening","outputTitle":"Calibrate","output":"Record 60 seconds speculating about a news story with graded certainty.","targetSeconds":60},{"title":"Vocabulary consolidation: B2 lexis","objective":"Recall and use ten high-value B2 items in argument.","canDo":"I can use precise B2 academic lexis to evaluate an argument.","skill":"vocabulary","input":"reading","outputTitle":"Ten-item production","output":"Record 90 seconds using eight of the ten items naturally.","targetSeconds":90},{"title":"Timed listening: three accents","objective":"Hold comprehension across accents and note-taking under time pressure.","canDo":"I can follow three accents on one topic and take usable notes without a transcript.","skill":"listening","input":"listening","outputTitle":"Notes and summary","output":"Take notes while listening once, then summarise in four sentences.","wordRange":[70,100]},{"title":"Timed reading: inference under pressure","objective":"Answer inference questions in a fixed time without rereading everything.","canDo":"I can answer inference questions against the clock with a defensible reason.","skill":"reading","input":"reading","outputTitle":"Inference answers","output":"Answer the questions in six minutes and justify each answer in one sentence.","wordRange":[70,100]},{"title":"Writing: final essay","objective":"Produce a 200–220-word essay under exam conditions.","canDo":"I can write a timed 200–220-word argument essay with evidence and a conclusion.","skill":"writing","input":"reading","outputTitle":"Final essay","output":"Write in 30 minutes, then spend five minutes editing for linkers and hedging.","wordRange":[200,220]},{"title":"Speaking: final B2 capstone","objective":"Sustain a three-minute talk plus follow-up questions.","canDo":"I can speak for three minutes on an abstract question and handle follow-ups confidently.","skill":"speaking","input":"listening","outputTitle":"Three-minute talk and follow-ups","output":"Use the final prompt card, then answer the three follow-up questions.","targetSeconds":180}],"releaseStage":"live"}]} $json$::jsonb) as imported_modules_7_8;

-- 4. Vocabulary windows and item counts ----------------------------------
-- Every lesson gets an 8-item vocabulary window (the architecture asks for
-- 8–12 items per lesson) and 10 practice items (it asks for 8–15).
insert into public.lesson_vocab (lesson_id, vocab_item_id, sort_order)
select l.id, it.id, 6 + k
from public.lessons l
join lateral (
  select vi.id, (row_number() over (order by vi.term) - 1) as idx, count(*) over () as total
  from public.vocab_items vi
  join public.vocab_decks vd on vd.id = vi.deck_id and vd.module_id = l.module_id
) it on true
cross join generate_series(1, 2) as k
where it.idx = ((l.module_lesson_number - 1 + 6 + k - 1) % it.total)
on conflict do nothing;

insert into public.practice_items (lesson_id, kind, sort_order, prompt, options, answer, explanation, grammar_point, difficulty)
select
  lv.lesson_id, 'multiple_choice', lv.sort_order + 2,
  format('Which expression matches this meaning? "%s"', vi.definition),
  jsonb_build_array(vi.term) || coalesce((
    select jsonb_agg(d.term order by d.term) from (
      select vi2.term from public.vocab_items vi2
      where vi2.deck_id = vi.deck_id and vi2.term <> vi.term
      order by md5(vi2.term || lv.sort_order::text), vi2.term limit 2) d), '[]'::jsonb),
  vi.term, format('Example: %s', vi.example), l.grammar_point, 1
from public.lesson_vocab lv
join public.vocab_items vi on vi.id = lv.vocab_item_id
join public.lessons l on l.id = lv.lesson_id
where lv.sort_order in (7, 8)
  and not exists (select 1 from public.practice_items p where p.lesson_id = lv.lesson_id and p.sort_order = lv.sort_order + 2);

update public.lesson_blocks b
   set content = jsonb_set(jsonb_set(b.content, '{item_count}', '10'::jsonb), '{mix}', '{"grammar":2,"vocabulary":8}'::jsonb)
 where b.block_kind = 'practice';

-- 5. Summary --------------------------------------------------------------
select jsonb_build_object(
  'modules', (select count(*) from public.modules),
  'lessons', (select count(*) from public.lessons),
  'lesson_blocks', (select count(*) from public.lesson_blocks),
  'practice_items', (select count(*) from public.practice_items),
  'vocab_items', (select count(*) from public.vocab_items),
  'content_inputs', (select count(*) from public.content_inputs),
  'speaking_tasks', (select count(*) from public.speaking_tasks),
  'writing_tasks', (select count(*) from public.writing_tasks),
  'checkpoints', (select count(*) from public.checkpoints),
  'badges', (select count(*) from public.badges)
) as seed_summary;
